import{_ as p,a0 as i,w as l,s as g,ao as a,I as r,a1 as o,A as s,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"通过网络方式安装 Debian 7（Wheezy） | LCTT x X-CMD","titleTemplate":false,"description":"通过网络方式安装 Debian 7（Wheezy） | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过网络方式安装 Debian 7（Wheezy） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过网络方式安装 Debian 7（Wheezy） | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140919 Network Installation of Debian 7 (Whezzy) on Client Machines using DNSMASQ Network Boot Server","title":"通过网络方式安装 Debian 7（Wheezy）","tag":"201411","desc":""},"relativePath":"201411/20140919 Network Installation of Debian 7 (Whezzy) on Client Machines using DNSMASQ Network Boot Server.md","filePath":"[post].md"}'),m={name:"201411/20140919 Network Installation of Debian 7 (Whezzy) on Client Machines using DNSMASQ Network Boot Server.md"};function d(w,t,u,D,c,b){const e=i("Link");return l(),g("div",null,[t[19]||(t[19]=a('<h1 id="通过网络方式安装-debian-7-wheezy" tabindex="-1">通过网络方式安装 Debian 7（Wheezy） <a class="header-anchor" href="#通过网络方式安装-debian-7-wheezy" aria-label="Permalink to “通过网络方式安装 Debian 7（Wheezy）”">​</a></h1><p>本教程将指引你直接通过使用<strong>DNSMASQ</strong>作为<strong>PXE服务器（预启动执行环境）</strong>，以网络方式安装<strong>Debian 7（Wheezy）</strong>，此种情况是假定你的服务器不提供任何CD/DVD/USB介质驱动器，或者它只能通过相连的监视器、键盘和鼠标操作。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Network-Debian-Instalaltion.png" alt="Debian 7 Network Installation on Client Machines"></p><p><em>客户机上的Debian 7网络安装</em></p><p><strong>DNSMASQ</strong>是一个轻量级网络基础架构服务器，它可以通过内建的DNS、DHCP和TFTP服务器提供如DNS、DHCP和网络启动等关键服务。</p><p>一旦PXE服务器启动并运行，你可以指示你所有的客户机直接从网络启动，前提是你的客户机必须拥有一张支持网络启动的网卡，网络启动可以从BIOS的网络启动或启动服务选项中启用。</p><h3 id="前置阅读" tabindex="-1">前置阅读 <a class="header-anchor" href="#前置阅读" aria-label="Permalink to “前置阅读”">​</a></h3>',7)),r("ul",null,[r("li",null,[o(e,{href:"http://www.tecmint.com/debian-gnulinux-7-0-code-name-wheezy-server-installation-guide/"},{default:s(()=>[...t[0]||(t[0]=[n("Debian 7 (Wheezy)安装指南",-1)])]),_:1})])]),t[20]||(t[20]=a(`<h3 id="步骤1-安装及配置dnsmasq服务器" tabindex="-1">步骤1： 安装及配置DNSMASQ服务器 <a class="header-anchor" href="#步骤1-安装及配置dnsmasq服务器" aria-label="Permalink to “步骤1： 安装及配置DNSMASQ服务器”">​</a></h3><p><strong>1.</strong> 首先，在安装Debian服务器后，要确保你的系统使用的是<strong>静态IP地址</strong>。因为除了网络启动之外，也要为你的整个网段提供DHCP服务。设置好静态IP地址后，以root帐号或具有root权力的用户来运行以下命令，进行DNSMASQ服务器的安装。</p><pre><code># apt-get install dnsmasq
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Install-Dnsmasq-in-Debian.png" alt="Install Dnsmasq Package"></p><p><em>安装Dnsmasq包</em></p><p><strong>2.</strong> 安装好DNSMASQ包后，你可以开始编辑配置文件。首先创建一个主配置文件的备份，然后使用下面的命令对<strong>dnsmasq.conf</strong>文件进行编辑。</p><pre><code># mv /etc/dnsmasq.conf  /etc/dnsmasq.conf.backup
# nano /etc/dnsmasq.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Backup-dnsmasq-Configuration-file.png" alt="Backup Dnsmasq Configuration"></p><p><em>备份Dnsmasq配置</em></p><p><strong>3.</strong> 上面的备份过程适合重命名配置文件，所以新的文件应该是空，你可以使用以下描述的<strong>DNSMASQ</strong>配置文件节录。</p><pre><code>interface=eth0
domain=debian.lan
dhcp-range=192.168.1.3,192.168.1.253,255.255.255.0,1h
dhcp-boot=pxelinux.0,pxeserver,192.168.1.100
pxe-prompt=&quot;Press F8 for menu.&quot;, 60
#pxe-service types: x86PC, PC98, IA64_EFI, Alpha, Arc_x86, Intel_Lean_Client, IA32_EFI, BC_EFI, Xscale_EFI and X86-64_EFI
pxe-service=x86PC, &quot;Install Debian 7 Linux from network server 192.168.1.100&quot;, pxelinux
enable-tftp
tftp-root=/srv/tftp
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Configure-dnsmasq.png" alt="Configuration of Dnsmasq"></p><p><em>Dnsmasq配置</em></p><ul><li><strong>interface</strong> – 服务器监听的网络接口。</li><li><strong>domain</strong> – 用你自己的域名替换。</li><li><strong>dhcp-range</strong> – 用你自己的网络掩码定义的网络IP地址范围。</li><li><strong>dhcp-boot</strong> – 保持默认，但使用你自己的服务器IP地址替换IP声明。</li><li><strong>pxe-prompt</strong> – 保持默认 – 要求在<strong>敲击F8键</strong> 进入菜单时等待60秒。</li><li><strong>pxe=service</strong> – 使用<strong>x86PC</strong>作为32位/64位架构，并进入引号字符串的菜单描述提示。其它值类型可能是：PC98，IA64_EFI，Alpha，Arc_x86，Intel_Lean_Client，IA32_EFI, BC_EFI，Xscale_EFI和 X86-64_EFI。</li><li><strong>enable-tftp</strong> – 启用内建TFTP服务器。</li><li><strong>tftp-root</strong> – 使用/srv/tftp作为Debian网络启动文件的存放位置。</li></ul><h3 id="步骤2-下载debian网络启动文件并打开防火墙连接" tabindex="-1">步骤2: 下载Debian网络启动文件并打开防火墙连接 <a class="header-anchor" href="#步骤2-下载debian网络启动文件并打开防火墙连接" aria-label="Permalink to “步骤2: 下载Debian网络启动文件并打开防火墙连接”">​</a></h3><p><strong>4.</strong> 现在，该下载Debian网络启动文件了。首先，修改你当前工作目录路径到<strong>TFTP根目录</strong>位置，此位置由最后的配置语句定义（<strong>/srv/tftp</strong>系统路径）。</p>`,16)),r("p",null,[t[3]||(t[3]=n("转到",-1)),o(e,{href:"http://www.debian.org/distrib/netinst#netboot"},{default:s(()=>[...t[1]||(t[1]=[n("Debian网络安装",-1)])]),_:1}),t[4]||(t[4]=n(" – ",-1)),o(e,{href:"http://ftp.nl.debian.org/debian/dists/wheezy/main/"},{default:s(()=>[...t[2]||(t[2]=[n("网络启动部分",-1)])]),_:1}),t[5]||(t[5]=n("的官方页面镜像，抓取以下文件，要抓取的文件取决于你想要安装到客户端的系统架构。",-1))]),t[21]||(t[21]=a(`<p>下载好<strong>netboot.tar.gz</strong>文件后，同时提取归档（该过程描述只适用于64位，但对于其它系统架构也基本相同）。</p><pre><code># cd /srv/tftp/
# wget http://ftp.nl.debian.org/debian/dists/wheezy/main/installer-amd64/current/images/netboot/netboot.tar.gz
# tar xfz netboot.tar.gz
# wget http://ftp.nl.debian.org/debian/dists/wheezy/main/installer-amd64/current/images/SHA256SUMS
# wget http://ftp.nl.debian.org/debian/dists/wheezy/Release
# wget http://ftp.nl.debian.org/debian/dists/wheezy/Release.gpg
</code></pre><p>同时，必须确保<strong>TFTP</strong>目录中的所有文件都可让TFTP服务器读取。</p><pre><code># chmod -R 755 /srv/tftp/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Download-Debian-NetBoot-Files.png" alt="Download Debian NetBoot Files"></p><p><em>下载Debian网络启动文件</em></p><p>使用以下变量用于<strong>Debian网络安装</strong>镜像和架构。</p><pre><code># wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/main/installer-&quot;$ARCH&quot;/current/images/netboot/netboot.tar.gz
# wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/main/installer-&quot;$ARCH&quot;/current/images/SHA256SUMS
# wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/Release
# wget http://&quot;$YOURMIRROR&quot;/debian/dists/wheezy/Release.gpg
</code></pre><p><strong>5.</strong> 下一步，启动或重启DNSMASQ守护进程，并运行netstat命令来获取服务器监听的端口列表。</p><pre><code># service dnsmasq restart
# netstat -tulpn | grep dnsmasq
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Start-Dnsmasq-Service.png" alt="Start Dnsmasq Service"></p><p><em>启动Dnsmasq服务</em></p><p><strong>6.</strong> 基于Debian的发行版通常附带了<strong>UFW防火墙</strong>包。使用以下命令来打开需要的<strong>DNSMASQ</strong>端口号：<strong>67</strong>（Bootps），<strong>69</strong>（TFTP），<strong>53</strong>（DNS）<strong>4011</strong>（代理DHCP）udp和<strong>53</strong> tcp（DNS）。</p><pre><code># ufw allow 69/udp
# ufw allow 4011/udp   ## Only if you have a ProxyDHCP on the network
# ufw allow 67/udp
# ufw allow 53/tcp
# ufw allow 53/udp
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Open-Dnsmasq-Ports-620x303.png" alt="Open Dnsmasq Ports"></p><p><em>开启Dnsmasq端口</em></p><p>现在，位于你的客户机网络接口上的PXE加载器将使用按以下顺序从<strong>/srv/tftp/pxelinux.cfg</strong>目录加载<strong>pxelinux</strong>配置文件。</p><ul><li>GUID文件</li><li>MAC文件</li><li>默认文件</li></ul><h3 id="步骤3-配置客户端从网络启动" tabindex="-1">步骤3： 配置客户端从网络启动 <a class="header-anchor" href="#步骤3-配置客户端从网络启动" aria-label="Permalink to “步骤3： 配置客户端从网络启动”">​</a></h3><p><strong>7.</strong> 要为你的客户端计算机启用网络启动，请进入系统<strong>BIOS配置</strong>（如何进入BIOS设置，请查阅硬件主板提供商的文档）。</p><p>转到<strong>启动菜单</strong>，然后选择<strong>网络启动</strong>作为<strong>首要启动设备</strong>（在某些系统上，你可以不用进入BIOS配置就能选择启动设备，只要在<strong>BIOS自检</strong>时按一个键就可以进行选择了）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Select-BIOS-Settings.png" alt="Select BIOS Settings"></p><p><em>选择BIOS设置</em></p><p><strong>8。</strong> 在编辑启动顺序后，通常按<strong>F10</strong>来保存BIOS设置。重启后，你的客户端计算机应该可以直接从网络启动了，应该会出第一个<strong>PXE</strong>提示，要求你按<strong>F8</strong>键进入菜单。</p><p>接下来，敲击<strong>F8</strong>键来进入，会出现一个新的提示。敲击<strong>回车</strong>键，屏幕上会出现<strong>Debian安装器</strong>主界面提示，如下图所示。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Boot-Menu-Selection.png" alt="Boot Menu Selection"></p><p><em>启动菜单选择</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Select-Debian-Installer-Boot.png" alt="Select Debian Installer Boot"></p><p><em>选择Debian安装器启动</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Select-Debian-Install.png" alt="Select Debian Install"></p><p><em>选择Debian安装</em></p><p>从这里开始，你可以使用Debian 7 Wheezy安装进程将Debian安装到你的机器上了（安装链接见上面）。然而，为了能够完成安装进程，你也需要确保你的机器上互联网连接已经激活。</p><h3 id="步骤4-dnsmasq服务器排障并在系统范围内启用" tabindex="-1">步骤4： DNSMASQ服务器排障并在系统范围内启用 <a class="header-anchor" href="#步骤4-dnsmasq服务器排障并在系统范围内启用" aria-label="Permalink to “步骤4： DNSMASQ服务器排障并在系统范围内启用”">​</a></h3><p><strong>9.</strong> 要诊断服务器以查询最终是否发生问题或要查询其它提供给客户端的信息，运行以下命令来打开日志文件。</p><pre><code># tailf /var/log/daemon.log
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Debbug-DNSMASQ-Server.png" alt="Debug DNSMASQ Server"></p><p><em>DNSMASQ服务器排障</em></p><p><strong>10.</strong> 如果服务器测试中已一切就绪，你现在可以在<strong>sysv-rc-conf</strong>包的帮助下，启用<strong>DNSMASQ</strong>守护进程自启动，以使该进程在系统重启后自动启动。</p><pre><code># apt-get install sysv-rc-conf
# sysv-rc-conf dnsmaq on
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Enable-DNSMASQ-Daemon.png" alt="Enable DNSMASQ Daemon"></p><p><em>启用DNSMASQ守护进程</em></p><p>到此为止吧！现在你的<strong>PXE</strong>服务器已经整装待发，随时准备好分配IP地址了（<strong>DHCP</strong>），并为你所有网段中的客户端提供需要的启动信息，这些信息配置用来从网络启动并安装Debian Wheezy。</p><p>使用PXE网络启动安装在服务器主机数量很多时很有优势，因为你可以在短时间内火同时设置整个网络基础架构，为版本升级提供了方便，也可以通过kickstart文件使整个安装的全自动化。</p><hr>`,44)),r("p",null,[t[7]||(t[7]=n("via: ",-1)),o(e,{href:"http://www.tecmint.com/network-installation-of-debian-7-on-client-machines/"},{default:s(()=>[...t[6]||(t[6]=[n("http://www.tecmint.com/network-installation-of-debian-7-on-client-machines/",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=n("作者：",-1)),o(e,{href:"http://www.tecmint.com/author/cezarmatei/"},{default:s(()=>[...t[8]||(t[8]=[n("Matei Cezar",-1)])]),_:1}),t[12]||(t[12]=n(" 译者：",-1)),o(e,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[9]||(t[9]=[n("GOLinux",-1)])]),_:1}),t[13]||(t[13]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[16]||(t[16]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:s(()=>[...t[15]||(t[15]=[n("Linux中国",-1)])]),_:1}),t[18]||(t[18]=n(" 荣誉推出",-1))])])}const I=p(m,[["render",d]]);export{f as __pageData,I as default};
